import type { z } from "zod";

/**
 * Validate an environment at start-up and, when it is wrong, say how to fix it.
 * Locally every value comes from a .env file generated by `bun env:pull`, so a
 * missing or stale file is the usual cause.
 *
 * The error names variables and never their values: it lands in terminals and
 * Worker logs.
 */
export function parseEnv<T extends z.ZodType>(schema: T, source: unknown): z.output<T> {
  const result = schema.safeParse(source);
  if (result.success) {
    return result.data;
  }

  const problems = result.error.issues.map(
    (issue) => `  - ${issue.path.join(".") || "(root)"}: ${issue.message}`,
  );
  throw new Error(
    [
      "Invalid environment:",
      ...problems,
      "Locally, regenerate the .env files with `bun env:pull` from the repo root.",
    ].join("\n"),
  );
}
